import{_ as a,b as i,a as l,aS as e}from"./chunks/framework.M2Whok06.js";const m=JSON.parse('{"title":"伟大的毛主席","description":"","frontmatter":{},"headers":[],"relativePath":"note/history/modern-chinese-history/教员.md","filePath":"note/history/modern-chinese-history/教员.md","lastUpdated":1733930263000}'),t={name:"note/history/modern-chinese-history/教员.md"},r=e(`<h1 id="伟大的毛主席" tabindex="-1">伟大的毛主席 <a class="header-anchor" href="#伟大的毛主席" aria-label="Permalink to &quot;伟大的毛主席&quot;">​</a></h1><div class="tip custom-block github-alert"><p class="custom-block-title">中国上下五千年千古第一人，中国历史上第一个喊出“人民万岁”的伟大领袖</p><p></p></div><p>中央军委主席，中国人民领袖，中国共产党员，无产阶级革命家，政治家，理论家，军事家，战略家，</p><p>红军长征 四渡赤水 三大战役总指挥</p><h2 id="重大成果" tabindex="-1">重大成果 <a class="header-anchor" href="#重大成果" aria-label="Permalink to &quot;重大成果&quot;">​</a></h2><ul><li>1958年中国第一台黑白电视机研制成功</li><li>1958年我国第一台电子计算机诞生</li><li>1958年7000千瓦研究性重水反应堆建成</li><li>1960年歼-6批量生产</li><li>1964年10月16日我国在西北地区成功爆 炸了第一颗原子弹，爆炸当量2万吨级</li><li>1965年我国自行设计Algol型编译系统问世</li><li>1965年人工合成牛胰岛素诞生</li><li>1965年65型接触式光刻机研制成功</li><li>1965年强-5首飞</li><li>1966年歼-7首飞</li><li>1967年6月17日我国在西北地区成功爆炸了第一颗氢弹，爆炸当量为百万吨级</li><li>1967年441-B晶体管通用电子计算机研制成功</li><li>1969年双水内冷式汽轮发动机研制成功</li><li>1969年大型煤气化熔炉研制成功</li><li>1970年第一艘核潜艇“长征一号”下水</li><li>1970年4月24日东方红1号人造卫星发射成功</li><li>1971年DF-5洲际导弹试射成功</li><li>1971年第一艘导弹驱逐舰下水</li><li>1972年第一颗实用新型氢弹爆炸成功</li><li>1972年2万吨级货轮“长风号”下水</li><li>1973年集成电路计算机150研制成功</li><li>1973年首株杂交水稻培育成功</li></ul><h2 id="重大战役" tabindex="-1">重大战役 <a class="header-anchor" href="#重大战役" aria-label="Permalink to &quot;重大战役&quot;">​</a></h2><p>1946年6月26日蒋介石公然撕毁和平协议，发动了全面内战，由郑州绥靖公署主任刘峙指挥22万兵力进攻中原部队，军令原文：“48小时全歼李先念中原军区部队！”</p><h3 id="辽沈战役" tabindex="-1">辽沈战役 <a class="header-anchor" href="#辽沈战役" aria-label="Permalink to &quot;辽沈战役&quot;">​</a></h3><ul><li>时间：1948年9月12日 至 1948年11月2日</li><li>地点：今辽宁省、吉林省</li><li>参战方兵力：中国人民解放军：60万，国民党军：80万</li><li>伤亡情况：辽沈战役历时52天，人民解放军伤亡6.9万人，歼敌47.2万</li><li>主要指挥官： 林彪、罗荣桓、刘亚楼;卫立煌、廖耀湘、‌杜聿明、‌陈诚、‌范汉杰、‌郑洞国</li><li>结果：战役结束后，中国人民解放军首次在兵力数量方面超越国民党军队，解放了东北全境。</li></ul><h3 id="淮海战役" tabindex="-1">淮海战役 <a class="header-anchor" href="#淮海战役" aria-label="Permalink to &quot;淮海战役&quot;">​</a></h3><ul><li>时间：1948年11月6日至1949年1月10日</li><li>地点：淮海地区</li><li>主要战役: 陈官庄战役、双堆集战役、碾庄战役</li><li>参战方兵力：中国人民解放军：60万，国民党军：80万</li><li>伤亡情况：中国人民解放军：伤亡十余万；国民党军：伤亡及被俘55万余</li><li>主要指挥官： 邓小平、刘伯承、陈毅、粟裕、谭震林;杜聿明、黄维、黄百韬、刘峙、邱清泉</li></ul><h3 id="平津战役" tabindex="-1">平津战役 <a class="header-anchor" href="#平津战役" aria-label="Permalink to &quot;平津战役&quot;">​</a></h3><ul><li>时间：1948年11月29日至1949年1月31日</li><li>地点：北平（北京）、天津一带</li><li>参战方兵力：中国人民解放军 100万人，国民党军 52万人</li><li>伤亡情况：人民解放军 伤亡3.9万人；歼灭和改编国民党军一个战略集团52万余人</li><li>主要指挥官： 林彪、罗荣桓、聂荣臻; 傅作义、郭景云</li><li>结 果: 基本上解放了华北全境</li></ul><h3 id="渡江战役" tabindex="-1">渡江战役 <a class="header-anchor" href="#渡江战役" aria-label="Permalink to &quot;渡江战役&quot;">​</a></h3><ul><li>时间：1949年4月20日 至 1949年6月2日</li><li>地点：长江中下游</li><li>参战方兵力：中国人民解放军120万人，国民党汤恩伯部、白崇禧部共约70万人；海军2个舰队和空军4个大队</li><li>伤亡情况：中国人民解放军伤亡6万余人；中华民国国军伤亡及投降共43万余人</li><li>主要指挥官： 毛泽东、朱德、刘伯承、邓小平、粟裕；蒋介石、李宗仁、汤恩伯、白崇禧</li><li>结 果:解放江南的大部分地区，一举突破国民党军的长江防线。</li></ul><h2 id="两弹一星" tabindex="-1">两弹一星 <a class="header-anchor" href="#两弹一星" aria-label="Permalink to &quot;两弹一星&quot;">​</a></h2><p>“两弹一星”最初是指原子弹、导弹和人造卫星。“两弹”中的一弹是原子弹，后来演变为原子弹和氢弹的合称；另一弹是指导弹。“一星”则是人造地球卫星。 1955年1月15日，毛泽东召开中共中央书记处扩大会议，会议决定中国要发展原子能事业。1964年10月16日我国第一颗原子弹爆炸成功，1967年6月17日我国第一颗氢弹空爆试验成功，1970年4月24日我国第一颗人造卫星发射成功。</p><h2 id="个人崇拜" tabindex="-1">个人崇拜 <a class="header-anchor" href="#个人崇拜" aria-label="Permalink to &quot;个人崇拜&quot;">​</a></h2><p>有人说，崇拜是一种迷信，但是为什么会使千千万的人民而崇拜呢？话说回来，让一个人来崇拜另外一个人，简单么？ 可以说非常的困难，几乎是不可能做到的事情。即便是你的孩子，你生他养他，他可以亲你，养你，但你也做不到让你的孩子崇拜你。</p><h2 id="最有力量的一段文字" tabindex="-1">最有力量的一段文字 <a class="header-anchor" href="#最有力量的一段文字" aria-label="Permalink to &quot;最有力量的一段文字&quot;">​</a></h2><p>&quot;由于我的职位低下，人们都不愿同我来往。我的职责中有一项是登记，来图书馆读报的人的姓名，可是他们大多数不把我当人看待。在那些来看报的人当中，我认出了些新文化运动的著名领导者的名字，如傅斯年、罗家伦等等，我对他们抱有强烈的兴趣。我曾经试图同他们交谈政治和文化问题，可是他们都是些大忙人，没有时间听一个图书馆助理员讲南方土话。&quot;</p><p>“但是我不因此而丧气，我仍然参加哲学研究会和新闻学研究会,想藉此能听大学里的课程。</p><p>我自己在北平的生活是十分困苦的。我家在一个叫三眼井的地方，和另外七个人合住一个小房间，我们全体挤在炕上，连呼吸的地方都没有。每逢我翻身都得预先警告身旁的人。不过在公园和故宫的宫址我看到了北国的早春，在坚冰还盖着北海的时候，我看到了怒放的梅花。北京的树木引起了我无穷的欣赏。&quot; ——教员</p><h2 id="四人帮" tabindex="-1">四人帮 <a class="header-anchor" href="#四人帮" aria-label="Permalink to &quot;四人帮&quot;">​</a></h2><p>“四人帮”是指王洪文、张春桥、江青、姚文元四人。</p><h2 id="汪东兴" tabindex="-1">汪东兴 <a class="header-anchor" href="#汪东兴" aria-label="Permalink to &quot;汪东兴&quot;">​</a></h2><p>汪东兴说 我作为多年跟随毛主席的警卫干部 接受毛主席的教育和思想很深。 这也大概就是我不能接受十 届三中全会路线以及为少奇同 志彻底平反等意见的主要原因 我的观点和思想与你们的许多 意见格格不入，彼此很难统一 在这种情况下，为了党的事业 和团结，我决定还是自已 辞职比较好。</p><h2 id="主席的诗" tabindex="-1">主席的诗 <a class="header-anchor" href="#主席的诗" aria-label="Permalink to &quot;主席的诗&quot;">​</a></h2><p>孩儿立志出乡关，学不成名誓不还。-- 出自毛泽东的《七绝·改西乡隆盛诗赠父亲》</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1910年秋天，毛泽东离开家乡韶山，走向外面更广阔的世界。这是他人生历程中的第一个转折。</span></span>
<span class="line"><span>怀着激动心情，临行前他写下这首诗，夹在父亲每天必看的帐簿里，以作告别。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div>`,31),o=[r];function s(n,h,d,c,p,u){return l(),i("div",null,o)}const q=a(t,[["render",s]]);export{m as __pageData,q as default};
